import math

def check_condition(n):
    """
    Checks if k^2 == 1 (mod n) for all k such that gcd(k, n) = 1.
    """
    print(f"\n--- Testing n = {n} ---")

    # Iterate through k from 1 up to n-1
    for k in range(1, n):
        if math.gcd(k, n) == 1:
            # Check the condition k^2 - 1 is divisible by n
            if (k * k - 1) % n != 0:
                print(f"Failed for k = {k}: {k}^2 - 1 = {k*k - 1}, which is not divisible by {n}.")
                return False

    print(f"Passed for n = {n}: All relevant k satisfy the condition.")
    return True

# Candidates to test
candidates = [9, 15, 16, 25]

results = {}
for n in candidates:
    results[n] = check_condition(n)

print("\n--- Summary ---")
for n, result in results.items():
    print(f"n={n} satisfies the condition: {result}")

import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def check_condition(n):
    if n < 2:
        return False

    # Test all k such that 1 <= k < n and gcd(k, n) = 1
    for k in range(1, n):
        if gcd(k, n) == 1:
            # Check if k^2 - 1 is a multiple of n
            if (k*k - 1) % n != 0:
                return False
    return True

solutions = []
for n in range(2, 31):
    if check_condition(n):
        solutions.append(n)

print(f"Solutions found up to 30: {solutions}")
